const body = $input.first().json.body;
const entry  = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
const contact = change?.contacts?.[0];

if (!message) return [{ json: { skip: true } }];

const base = {
  skip: false,
  isUnsupported: false,
  isInteractive: false,
  phoneNumber: message.from,
  phoneNumberId: change.metadata.phone_number_id,
  contactName: contact?.profile?.name || 'Student',
  timestamp: message.timestamp,
};

if (message.type === 'interactive' && message.interactive?.type === 'list_reply') {
  const r = message.interactive.list_reply;
  return [{ json: { ...base, isInteractive: true, selectionId: r.id, selectionTitle: r.title, query: r.title } }];
}

if (message.type === 'interactive' && message.interactive?.type === 'button_reply') {
  const r = message.interactive.button_reply;
  return [{ json: { ...base, isInteractive: true, selectionId: r.id, selectionTitle: r.title, query: r.title } }];
}

if (message.type !== 'text') {
  return [{ json: { ...base, isUnsupported: true, response: 'I only understand text messages and menu selections.' } }];
}

return [{ json: { ...base, query: message.text.body } }];

const msgData = $('Extract Message').first().json;
const query = (msgData.query || '').trim();

// Look for this phone number in the registered students list
let registrationRow = null;
try {
  const rows = $input.all();
  const match = rows.find(r => String(r.json.WhatsApp_Number || '').trim() === String(msgData.phoneNumber).trim());
  if (match) registrationRow = match.json;
} catch(e) {}

// Registered path
if (registrationRow) {
  return [{ json: {
    isRegistered: true,
    action: 'registered',
    phoneNumber: msgData.phoneNumber,
    phoneNumberId: msgData.phoneNumberId,
    contactName: msgData.contactName,
    query: msgData.query,
    isInteractive: msgData.isInteractive,
    selectionId: msgData.selectionId,
    selectionTitle: msgData.selectionTitle,
    savedSection: registrationRow.Sheet_Tab,
    savedSectionName: registrationRow.Section_Name,
    savedRollNumber: registrationRow.Roll_Number,
  }}];
}

// Not registered: parse roll number + section from the message
const rollMatch = query.match(/\b(\d{2}BCON\d{4})\b/i);
const rollNumber = rollMatch ? rollMatch[1].toUpperCase() : null;

const sectionMap = [
  { re: /\bsec[\s-]?sk\b|\bsection\s+sk\b/i, tab: 'Sec-SK', name: 'Section SK' },
  { re: /\bsd\s+b\b|\bsoftware\s+(dev|development)\s+b\b/i, tab: 'CSE_SD_Sec_B', name: 'Software Dev (Sec B)' },
  { re: /\bsd\b|\bsoftware\s+(dev|development)\b/i, tab: 'CSE_SD_Sec_A', name: 'Software Dev (Sec A)' },
  { re: /\baiml\s+b\b|\bai\s+b\b/i, tab: 'CSE_AIML_Sec_B', name: 'AI & ML (Sec B)' },
  { re: /\baiml\b|\bartificial\s+intelligence\b|\bmachine\s+learning\b/i, tab: 'CSE_AIML_Sec_A', name: 'AI & ML (Sec A)' },
  { re: /\bcys\s+b\b|\bcyber\s*(sec|security)?\s+b\b/i, tab: 'CSE_CyberSec_Sec_B', name: 'Cyber Security (Sec B)' },
  { re: /\bcys\b|\bcyber\s*(sec|security)?\b/i, tab: 'CSE_CyberSec_Sec_A', name: 'Cyber Security (Sec A)' },
  { re: /\bibm\b/i, tab: 'CSE_IBM_Sec_A', name: 'IBM (Sec A)' },
  { re: /\bxebia\b/i, tab: 'CSE_Xebia_Sec_A', name: 'Xebia (Sec A)' },
];

let sheetTab = null, detectedSectionName = null;
for (const m of sectionMap) {
  if (m.re.test(query)) { sheetTab = m.tab; detectedSectionName = m.name; break; }
}

return [{ json: {
  isRegistered: false,
  action: (rollNumber && sheetTab) ? 'register' : 'prompt',
  phoneNumber: msgData.phoneNumber,
  phoneNumberId: msgData.phoneNumberId,
  contactName: msgData.contactName,
  query: msgData.query,
  rollNumber: rollNumber || '',
  sheetTab: sheetTab || '',
  detectedSectionName: detectedSectionName || '',
}}];

const input = $input.first().json;
const id = (input.selectionId || '').trim();

if (id.startsWith('SECTION|')) {
  const tab = id.replace('SECTION|', '');
  const labels = {
    'CSE_SD_Sec_A': 'Software Dev (Sec A)', 'CSE_SD_Sec_B': 'Software Dev (Sec B)',
    'CSE_AIML_Sec_A': 'AI & ML (Sec A)', 'CSE_AIML_Sec_B': 'AI & ML (Sec B)',
    'CSE_CyberSec_Sec_A': 'Cyber Security (Sec A)', 'CSE_CyberSec_Sec_B': 'Cyber Security (Sec B)',
    'CSE_IBM_Sec_A': 'IBM (Sec A)', 'CSE_Xebia_Sec_A': 'Xebia (Sec A)', 'Sec-SK': 'Section SK',
  };
  return [{ json: { ...input, isTimestableRequest: false, detectedSection: tab, detectedSectionName: labels[tab] || tab, detectedDay: null, fullDayRange: null } }];
}

const parts = id.split('|');
if (parts.length === 2 && parts[0] && parts[1]) {
  const tab = parts[0], day = parts[1];
  const labels = {
    'CSE_SD_Sec_A': 'Software Dev (Sec A)', 'CSE_AIML_Sec_A': 'AI & ML (Sec A)',
    'CSE_CyberSec_Sec_A': 'Cyber Security (Sec A)', 'CSE_IBM_Sec_A': 'IBM (Sec A)',
    'CSE_Xebia_Sec_A': 'Xebia (Sec A)', 'Sec-SK': 'Section SK',
  };
  return [{ json: { ...input, isTimestableRequest: true, detectedSection: tab, detectedSectionName: labels[tab] || tab, detectedDay: day, fullDayRange: `${tab}!A:H` } }];
}

return [{ json: { ...input, isTimestableRequest: false, detectedSection: null, detectedSectionName: null, detectedDay: null, fullDayRange: null } }];

const input = $input.first().json;
const query = (input.query || '').trim();
const queryLower = query.toLowerCase();

const detectedSection = input.savedSection;
const detectedSectionName = input.savedSectionName;

const dayMap = {
  'monday': 'Monday', 'mon': 'Monday',
  'tuesday': 'Tuesday', 'tue': 'Tuesday',
  'wednesday': 'Wednesday', 'wed': 'Wednesday',
  'thursday': 'Thursday', 'thu': 'Thursday',
  'friday': 'Friday', 'fri': 'Friday',
  'saturday': 'Saturday', 'sat': 'Saturday',
};

const now = new Date();
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let detectedDay = null;

if (['today','aaj'].some(w => queryLower.includes(w))) {
  detectedDay = dayNames[now.getDay()];
} else if (['tomorrow','kal'].some(w => queryLower.includes(w))) {
  const tmp = new Date(now); tmp.setDate(tmp.getDate()+1);
  detectedDay = dayNames[tmp.getDay()];
} else {
  for (const [k,v] of Object.entries(dayMap)) {
    if (queryLower.includes(k)) { detectedDay = v; break; }
  }
}

const fullDayRange = detectedSection ? `${detectedSection}!A:H` : null;

return [{ json: { ...input, detectedSection, detectedSectionName, detectedDay, hasDay: !!detectedDay, fullDayRange } }];

const rows = $input.all().map(i => i.json);

let preprocessed = {};
try { preprocessed = $('Registered Preprocessor').first().json; } catch(_) {
  try { preprocessed = $('Parse Selection').first().json; } catch(__) {}
}

const requestedDay = preprocessed.detectedDay;

const slots = [
  { col: 'Lecture 1 (8.00-8.50)',   time: '8:00-8:50 AM'   },
  { col: 'Lecture 2 (8.50-9.40)',   time: '8:50-9:40 AM'   },
  { col: 'Lecture 3 (9.40-10.30)',  time: '9:40-10:30 AM'  },
  { col: 'Lecture 4 (10.30-11.20)', time: '10:30-11:20 AM' },
  { col: 'Lecture 5 (11.20-12.05)', time: '11:20-12:05 PM' },
  { col: 'Lecture 6 (12.05-12.50)', time: '12:05-12:50 PM' },
];

function formatDay(row) {
  const day = row['Day/Time'] || '';
  const lines = ['📅 *' + day + '*'];
  let lastVal = '';
  for (const slot of slots) {
    let val = (row[slot.col] || '').trim();
    if (!val && lastVal) { val = lastVal + ' (cont.)'; }
    else { lastVal = val || ''; }
    if (val && val !== 'N/A') {
      lines.push('⏰ ' + slot.time + '\n   📚 ' + val);
    } else {
      lastVal = '';
      lines.push('⏰ ' + slot.time + '\n   Free Period');
    }
  }
  return lines.join('\n');
}

let formatted = [];
if (requestedDay) {
  const dayRow = rows.find(r => r['Day/Time']?.toLowerCase() === requestedDay.toLowerCase());
  formatted.push(dayRow ? formatDay(dayRow) : 'No schedule found for ' + requestedDay + '.');
} else {
  for (const row of rows) {
    if (row['Day/Time'] && row['Day/Time'] !== 'Day/Time') formatted.push(formatDay(row));
  }
}

const label = preprocessed.detectedDay
  ? '📊 ' + preprocessed.detectedDay + ' — ' + (preprocessed.detectedSectionName || preprocessed.detectedSection || '')
  : '📊 Full Week — ' + (preprocessed.detectedSectionName || preprocessed.detectedSection || '');

return [{ json: { ...preprocessed, response: label + '\n\n' + formatted.join('\n\n') } }];

const regData = $('Registration Gate').first().json;
const msgData = $('Extract Message').first().json;
return [{ json: {
  phoneNumber: msgData.phoneNumber,
  phoneNumberId: msgData.phoneNumberId,
  response: `✅ *Welcome, ${msgData.contactName}!*

You're registered as:
📋 Roll No: *${regData.rollNumber}*
📚 Section: *${regData.detectedSectionName}*

You can now check your timetable!
Just type a day like:
• "Monday"
• "Thursday schedule"
• "Today"

I'll show your ${regData.detectedSectionName} timetable instantly. 📅`
}}];
